//         "UniqueTotalQuestions", DISTINCTCOUNT('cube_question_summary_overall'[Question_No])
//     ),
//     [UniqueTotalQuestions]
// )

CALCULATE(
    COUNTROWS(
        SUMMARIZE(
            FILTER(
                'cube_question_summary_overall',
                NOT(ISBLANK('cube_question_summary_overall'[Standards])) &&
                CALCULATE(COUNTROWS('cube_question_summary_overall')) > 0
            ),
            'cube_question_summary_overall'[Standards],
            'cube_question_summary_overall'[Question_No]
        )
    )
)

