// VAR CombinedDetails = 
//     CONCATENATEX(
//         FILTER(
//             VALUES(cube_question_summary_overall[Position_Number]), 
//             NOT(ISBLANK(cube_question_summary_overall[Position_Number])) && 
//             cube_question_summary_overall[Position_Number] <> "N/A"
//         ),
//         cube_question_summary_overall[Position_Number] & ":  " & 
//         FIRSTNONBLANK(cube_question_summary_overall[Correct_Answer], 1), 
//         UNICHAR(10)  -- Line break
//     )
// RETURN 
//     IF(
//         ISBLANK(CombinedDetails),
//         FIRSTNONBLANK(cube_question_summary_overall[Correct_Answer], 1), 
//         CombinedDetails
//     )

VAR CombinedDetails = 
    CONCATENATEX(
        FILTER(
            VALUES(cube_question_summary_overall[Position_Number]), 
            NOT(ISBLANK(cube_question_summary_overall[Position_Number])) && 
            cube_question_summary_overall[Position_Number] <> "N/A" &&
            NOT(ISBLANK(FIRSTNONBLANK(cube_question_summary_overall[Correct_Answer], 1))) -- Ensure Correct_Answer is not blank
        ),
        VAR CorrectAns = FIRSTNONBLANK(cube_question_summary_overall[Correct_Answer], 1)
        RETURN 
            IF(
                ISBLANK(CorrectAns), 
                "",  -- If Correct_Answer is blank, return empty
                cube_question_summary_overall[Position_Number] & ": " & CorrectAns
            ), 
        UNICHAR(10),  -- Line break
        VALUE(cube_question_summary_overall[Position_Number]),  -- Sorting column
        ASC  -- Sort in ascending order
    )

RETURN 
    IF(
        ISBLANK(CombinedDetails),
        FIRSTNONBLANK(cube_question_summary_overall[Correct_Answer], 1), 
        CombinedDetails
    )

