VAR GradeAverage = MAX(cube_question_summary_overall[Grade_Average])

RETURN
IF (
    GradeAverage = 1,  -- If 100%, return blank
    BLANK(),

    VAR FilteredTable =
        FILTER (
            cube_question_summary_overall,
            NOT ISBLANK(cube_question_summary_overall[Position_Number]) &&
            cube_question_summary_overall[Position_Number] <> "N/A" &&
            NOT ISBLANK(cube_question_summary_overall[Incorrect_Details_Name])
        )

    VAR DistinctCombined =
        DISTINCT (
            SELECTCOLUMNS (
                FilteredTable,
                "ConcatValue",
                cube_question_summary_overall[Position_Number] & ": " & cube_question_summary_overall[Incorrect_Details_Name],
                "SortOrder", VALUE(cube_question_summary_overall[Position_Number])
            )
        )

    VAR Result =
        CONCATENATEX (
            DistinctCombined,
            [ConcatValue],
            UNICHAR(10),
            [SortOrder],
            ASC
        )

    RETURN
        IF (
            ISBLANK(Result),
            FIRSTNONBLANK(cube_question_summary_overall[Incorrect_Details_Name], 1),
            Result
        )
)


