// VAR FirstStandard = 
//     LEFT(FullStandards, 
//         FIND(",", FullStandards & ",") - 1
//     )

// RETURN
//     CALCULATE(
//         MAX(cube_question_summary_overall[Description]),
//         cube_question_summary_overall[Standards] = FirstStandard
//     )

VAR FullStandards =
CONCATENATEX(
        DISTINCT(cube_question_summary_overall[Standards]), 
        cube_question_summary_overall[Standards], 
        ", "
    )

VAR FirstStandard = 
    TRIM(LEFT(FullStandards, FIND(",", FullStandards & ",") - 1))

VAR RemainingStandards = 
    TRIM(
        SUBSTITUTE(FullStandards, FirstStandard & ",", "")
    )

VAR ChosenStandard = 
    IF(
        LOWER(FirstStandard) = "other",
        TRIM(LEFT(RemainingStandards, FIND(",", RemainingStandards & ",") - 1)),
        FirstStandard
    )

RETURN
    CALCULATE(
        MAX(cube_question_summary_overall[Description]),
        cube_question_summary_overall[Standards] = ChosenStandard
    )
